# Ronda 5 (septiembre 2026): pestaña Exportar, secciones plegables, modo presentación, mercado de destino y comparación.
# {t} y {usd} se expanden a todas las formas que producen los formateadores (Mt / mil t / t; mil M / M / mil).
# ---------------------------------------------------------------------------
_FORMAS = {
    "{t}": [("# Mt", "# Mt"), ("# mil t", "#k t"), ("# t", "# t")],
    "{usd}": [("US$# mil M", "US$#B"), ("US$# M", "US$# M"), ("< US$# M", "< US$# M"), ("US$# mil", "US$#k")],
}


def variantes(tabla):
    """Expande {t} y {usd} (en el mismo orden en español y en inglés) a todas sus formas."""
    salida = {}
    pendientes = list(tabla.items())
    while pendientes:
        es, en = pendientes.pop()
        marca = next((m for m in _FORMAS if m in es), None)
        if marca is None:
            salida[es] = en
            continue
        for a, b in _FORMAS[marca]:
            pendientes.append((es.replace(marca, a, 1), en.replace(marca, b, 1)))
    return salida


